function ord(s)
{
    return s.charCodeAt();
}

function chr(i)
{
    return String.fromCharCode(i);
}

function Script(s)
{
    this["+"] = s[0];
    this["-"] = s[1];
    for (var i = 0; i < 10; i++) {
        var c = chr(ord("0") + i)
        this[c] = s[2 + i];
    }
}

Script.prototype.translate = function(s) {
    var script = this;
    var trans_char = function(c) {
        var t = script[c];
        if (t === undefined)
            t = c;
        return t;
    }
    return s.replace(/./g, trans_char);
}

var sup = new Script("⁺⁻⁰¹²³⁴⁵⁶⁷⁸⁹");
var sub = new Script("₊₋₀₁₂₃₄₅₆₇₈₉");
var misc = {
    "->": "→",
    "=": "⇌",
    ".": "·",
    "*": "·",
};

var _regexp = [
    /([\]\)A-Za-z])([0-9]*)([+-]?)/,
    /(\s+)([0-9]+[+-])/,
    /(->|[=.*])/
];
_regexp = _regexp.map(function(re) { return re.source }).join("|");
_regexp = new RegExp(_regexp, "g");

function translate(formula)
{
    var translate_one = function(match, g1, g1a, g1b, g2, g2a, g3)
    {
        if (g1 !== undefined)
            return g1 + sub.translate(g1a) + sup.translate(g1b);
        if (g2 !== undefined)
            return sup.translate(g2a);
        if (g3 !== undefined)
            return misc[g3];
    }
    return formula.replace(_regexp, translate_one);
}


// 主函数 exec()
function exec(){
 var asc = quickerGetVar('origin');  // 读取context变量值, (context 是动作里的变量)
 var result = translate(asc);
 quickerSetVar('result', result ); //输出修改后的值到name变量中。
 return 0; //返回0表示成功。返回其他数字表示失败。
}

